head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > copyType]<br/>GridView 에서 복사/붙여넣기를 위한 데이터 선택 방식을 설정합니다.",
    "validation" : [
        "여러 Cell 이 직사각형 형태로 선택되었을때 동일 데이터가 전체 Cell 에 붙여넣기 됩니다.",
        "여러 Cell 이 형태 없이 선택된 경우 붙여넣기가 되지 않습니다.",
        "copyType='native' 일때 copyOption 은 항상 'display' 로 동작합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - source(복사 원본) 그리드 + target(붙여넣기 대상) 그리드 2개 구성
//  - 두 그리드 모두 copyType="native" 고정 : 웹브라우저 기본 복사/붙여넣기 방식
//    · native 는 셀 단위가 아닌 '텍스트' 선택/복사 → source 셀의 텍스트를 DOM Selection 으로 선택/복사 후 target 에 붙여넣기
//    · copyOption="dataList" 로 고정 설정해도 native 시 copyOption 은 항상 "display" 로 동작 (@spec)
//  - col2(금액) 에 displayFormat="#,##0" 적용 → 원본("1234567") 과 표시값("1,234,567") 이 다름
scwin.comp_init = async function () {
    // 기존 target / source / dataList 삭제
    if (typeof dlt_src !== 'undefined') {
        $p.data.remove("dlt_src");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target_src !== 'undefined') {
        target_src.remove();
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 : copyType="native" + copyOption="dataList" 고정
    //  - copyOption 을 dataList 로 고정해도 native 환경에서는 항상 display 로 동작함을 검증 (@spec)
    let properties = {
        focusMode : "cell",
        copyType : "native",
        copyOption : "dataList"
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="copyType=native, copyOption=dataList(고정). source 셀의 텍스트를 선택/복사하여 target 에 붙여넣기. 직사각형 선택=동일 데이터 전체, 형태없음(불연속)=미동작. copyOption=dataList 로 설정해도 native 는 항상 display(표시값) 복사. col2 는 displayFormat(천단위콤마) 적용. 결과는 하단 출력 영역에 표시"', '', 'label1');

    // source dataList 생성 (복사 원본 - col2 는 금액 원본값, displayFormat 으로 천단위 콤마 표시)
    $c.gcm.createDynamicDataList('', '', 'dlt_src');
    dlt_src.setJSON([
        { col1 : "RowA", col2 : "1234567", col3 : "AAA", col4 : "TextA" },
        { col1 : "RowB", col2 : "2200000", col3 : "BBB", col4 : "TextB" },
        { col1 : "RowC", col2 : "30500",   col3 : "CCC", col4 : "TextC" },
        { col1 : "RowD", col2 : "888",     col3 : "DDD", col4 : "TextD" }
    ]);

    // target dataList 생성 (붙여넣기 대상 - 초기값 Origin...)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { col1 : "Origin0_0", col2 : "10", col3 : "Origin0_2", col4 : "Origin0_3" },
        { col1 : "Origin1_0", col2 : "20", col3 : "Origin1_2", col4 : "Origin1_3" },
        { col1 : "Origin2_0", col2 : "30", col3 : "Origin2_2", col4 : "Origin2_3" },
        { col1 : "Origin3_0", col2 : "40", col3 : "Origin3_2", col4 : "Origin3_3" },
        { col1 : "Origin4_0", col2 : "50", col3 : "Origin4_2", col4 : "Origin4_3" }
    ]);

    // source 그리드 생성 (복사 원본 - col2 displayFormat="#,##0" 으로 원본 != 표시)
    let strSrc = '';
    strSrc += '<w2:gridView ' + strNameSpace + ' ' + cList + ' dataList="data:dlt_src" checkAllType="false" id="" style="width:520px;height:170px;">';
    strSrc += '<w2:caption style="" id="captionSrc" value="source (복사 원본) : col2(금액) 은 displayFormat 천단위콤마"></w2:caption>';
    strSrc += '<w2:header style="" id="headerSrc">';
    strSrc += '<w2:row style="" id="rowSrc1">';
    strSrc += '<w2:column width="100" style="" inputType="text" id="columnSrc1" value="이름"></w2:column>';
    strSrc += '<w2:column width="130" style="" inputType="text" id="columnSrc2" value="금액"></w2:column>';
    strSrc += '<w2:column width="100" style="" inputType="text" id="columnSrc3" value="코드"></w2:column>';
    strSrc += '<w2:column width="100" style="" inputType="text" id="columnSrc4" value="비고"></w2:column>';
    strSrc += '</w2:row>';
    strSrc += '</w2:header>';
    strSrc += '<w2:gBody style="" id="gBodySrc">';
    strSrc += '<w2:row style="" id="rowSrc2">';
    strSrc += '<w2:column width="100" style="" inputType="text" id="col1"></w2:column>';
    strSrc += '<w2:column width="130" style="" inputType="text" id="col2" dataType="number" displayFormat="#,##0"></w2:column>';
    strSrc += '<w2:column width="100" style="" inputType="text" id="col3"></w2:column>';
    strSrc += '<w2:column width="100" style="" inputType="text" id="col4"></w2:column>';
    strSrc += '</w2:row>';
    strSrc += '</w2:gBody>';
    strSrc += '</w2:gridView>';

    scwin.target_src = await $p.dynamicCreate(
        "target_src",
        "gridView",
        strSrc,
        grp_comp
    );

    // target 그리드 생성 (붙여넣기 대상 - editType="text", col2 동일 displayFormat)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:520px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="target (붙여넣기 대상) : 초기값 Origin..."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" editType="text"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="col2" editType="text"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" editType="text"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" editType="text"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}
